#include "observation_model.hpp"
#include "tolerance_metrics.hpp"
#include "table.hpp"
#include <set>
#include <tuple>
#include <iostream>
using namespace semes;
struct Configuration{int degree;double shrink;std::string scope;Json json()const{Json j=Json::dict();j["degree"]=degree;j["shrink"]=shrink;j["scope"]=scope;return j;}};
static std::vector<Configuration> configurations(){std::vector<Configuration> r;for(auto pair:{std::pair<int,std::string>{1,"all"},{2,"all"},{1,"mixed"}})for(double shrink:{.01,.1})r.push_back({pair.first,shrink,pair.second});return r;}
static std::vector<int> ids(const Json& j){std::vector<int> r;for(const auto& v:j.array)r.push_back(int(v.num()));return r;}
static cv::Mat array(const Npy& a){if(a.shape.size()!=2)throw std::runtime_error("Rank-two feature array required");cv::Mat r(int(a.shape[0]),int(a.shape[1]),CV_64F);for(size_t i=0;i<a.count();++i)r.ptr<double>()[i]=a.number(i);return r;}
struct StaticPrediction{std::string condition,protocol;int row;cv::Vec2d q;};
int wmain(int argc,wchar_t** wide){Utf8Arguments args(argc,wide);auto argv=args.data();try{
    if(argc!=5)throw std::runtime_error("evaluate_static features.npz aligned-manifest.csv preserved-selection-splits.json new-output");auto features=npz(fs::u8path(argv[1]));CsvTable manifest(fs::u8path(argv[2]));auto splits=Json::parse(read(fs::u8path(argv[3])));fs::path out=fs::u8path(argv[4]);if(fs::exists(out))throw std::runtime_error("New output required");fs::create_directories(out);int n=int(manifest.rows.size());cv::Mat truth(n,2,CV_64F);std::vector<std::string> dates;for(int i=0;i<n;++i){truth.at<double>(i,0)=manifest.number(i,"Y");truth.at<double>(i,1)=manifest.number(i,"T");dates.push_back(manifest.text(i,"dataset"));}
    auto configs=configurations();Json audit=Json::list();std::vector<StaticPrediction> all_predictions;int fits=0;Json protocol=Json::dict();protocol["status"]="exposed development comparison; not new photos";protocol["configs"]=Json::list();for(const auto& c:configs)protocol["configs"].push(c.json());protocol["selection"]="average per-date inner failure rate, then maximum error, then mean error; same historical inner/outer folds";protocol["conditions"]=Json::list();for(auto name:{"qr","upper","lower","both"})protocol["conditions"].push(name);protocol["original_cases"]=n;write(out/"static_protocol.json",protocol.dump());
    for(std::string condition:{"qr","upper","lower","both"}){
        auto X=array(features.at("X_"+condition));const auto& success=features.at("success_"+condition);if(X.rows!=n||success.count()!=size_t(n))throw std::runtime_error("Feature/manifest row count mismatch");
        auto train_model=[&](const Configuration& config,const std::vector<int>& candidates){std::vector<int> selected;for(int i:candidates)if(success.number(i)!=0)selected.push_back(i);std::vector<std::string> selected_dates;std::vector<int> source_indices;for(int i:selected){selected_dates.push_back(dates.at(i));source_indices.push_back(int(manifest.number(i,"index")));}ObservationModel model(config.degree,config.shrink,config.scope);model.fit(numeric::rows(X,selected),numeric::rows(truth,selected),selected_dates,source_indices);++fits;return model;};
        auto predict=[&](const ObservationModel& model,const std::vector<int>& candidates){cv::Mat p(int(candidates.size()),2,CV_64F,cv::Scalar(std::numeric_limits<double>::quiet_NaN()));std::vector<int> selected,positions;for(int i=0;i<int(candidates.size());++i)if(success.number(candidates[i])!=0){selected.push_back(candidates[i]);positions.push_back(i);}if(!selected.empty()){auto q=model.predict(numeric::rows(X,selected));for(int i=0;i<q.rows;++i)q.row(i).copyTo(p.row(positions[i]));}return p;};
        for(int fold=0;fold<5;++fold){
            const auto& inner=fold<4?splits.at(fold).at("inner_splits"):splits.at(splits.size()-1).at("full_selection").at("inner_splits");std::vector<int> train,test;for(int i=0;i<n;++i){if(fold==4||int(manifest.number(i,"fold"))!=fold)train.push_back(i);if(fold==4||int(manifest.number(i,"fold"))==fold)test.push_back(i);}
            Json scores=Json::list();std::tuple<double,double,double> best{std::numeric_limits<double>::infinity(),0,0};int chosen=-1;
            for(int k=0;k<int(configs.size());++k){std::map<std::string,std::pair<int,int>> date_errors;double sum_error=0,max_error=0;int finite_rows=0;
                for(const auto& split:inner.array){auto it=ids(split.at("train")),iv=ids(split.at("validation"));std::set<std::string> groups;for(int i:it)groups.insert(manifest.text(i,"cv_group"));for(int i:iv)if(groups.count(manifest.text(i,"cv_group")))throw std::runtime_error("Inner validation group overlaps training");auto model=train_model(configs[k],it);auto p=predict(model,iv);
                    for(int row=0;row<p.rows;++row){int i=iv[row];bool finite=cv::checkRange(p.row(row));bool bad=!finite;if(finite){++finite_rows;for(int axis=0;axis<2;++axis){double e=std::abs(p.at<double>(row,axis)-truth.at<double>(i,axis));sum_error+=e;max_error=std::max(max_error,e);bad=bad||e>.09+1e-12;}}auto& count=date_errors[dates[i]];++count.first;count.second+=bad;}
                }
                double balanced=0;for(auto& pair:date_errors)balanced+=double(pair.second.second)/pair.second.first;balanced/=date_errors.size();double maximum=finite_rows?max_error:1e100,mean=finite_rows?sum_error/(finite_rows*2):1e100;Json score=Json::dict();score["candidate"]=k;score["config"]=configs[k].json();score["balanced_failures"]=balanced;score["maximum"]=maximum;score["mean"]=mean;scores.push(score);auto rank=std::make_tuple(balanced,maximum,mean);if(chosen<0||rank<best){best=rank;chosen=k;}
            }
            auto model=train_model(configs.at(chosen),train);auto p=predict(model,test);std::string protocol=fold<4?"development_oof":"training_reapplication";for(int i=0;i<p.rows;++i)all_predictions.push_back({condition,protocol,test[i],{p.at<double>(i,0),p.at<double>(i,1)}});auto bundle=model.json();bundle["condition"]=condition;bundle["config"]=configs[chosen].json();bundle["scope_notice"]="Exposed development training artifact; no independent performance claim";write(out/fs::u8path(condition+(fold<4?"_fold"+std::to_string(fold):"_model")+".json"),bundle.dump());Json record=Json::dict();record["condition"]=condition;record["fold"]=fold;record["chosen"]=chosen;record["inner_splits"]=inner;record["scores"]=scores;audit.push(record);std::cout<<condition<<" fold="<<fold<<" chosen="<<chosen<<std::endl;
        }
    }
    write(out/"static_selection.json",audit.dump());std::ofstream predictions(out/"static_predictions.csv");for(size_t k=0;k<manifest.header.size();++k)predictions<<(k?",":"")<<csv(manifest.header[k]);predictions<<",condition_name,protocol,predY,predT,eY,eT,passed\n";predictions<<std::setprecision(17);
    std::map<std::pair<std::string,std::string>,std::vector<StaticPrediction>> groups;for(const auto& r:all_predictions){for(size_t k=0;k<manifest.header.size();++k)predictions<<(k?",":"")<<csv(manifest.rows[r.row][k]);double ey=std::abs(r.q[0]-truth.at<double>(r.row,0)),et=std::abs(r.q[1]-truth.at<double>(r.row,1));predictions<<','<<r.condition<<','<<r.protocol<<','<<r.q[0]<<','<<r.q[1]<<','<<ey<<','<<et<<','<<(ey<=.09+1e-12&&et<=.09+1e-12?"True":"False")<<'\n';groups[{r.condition,r.protocol}].push_back(r);}
    std::ofstream summary(out/"static_summary.csv");summary<<"condition_name,protocol,dataset,n,failures,passed,Y_MAE,Y_max,T_MAE,T_max\n";for(const auto& group:groups)for(std::string dataset:{"all","20261014","20261020"}){cv::Mat y,p;for(const auto& r:group.second)if(dataset=="all"||dates[r.row]==dataset){y.push_back(truth.row(r.row));cv::Mat pair=(cv::Mat_<double>(1,2)<<r.q[0],r.q[1]);p.push_back(pair);}auto metrics=tolerance_metrics(y,p);summary<<group.first.first<<','<<group.first.second<<','<<dataset;for(auto key:{"n","failures","passed","Y_MAE","Y_max","T_MAE","T_max"})summary<<','<<metrics.at(key).dump();summary<<'\n';}
    Json check=Json::dict();check["conditions"]=4;check["outer_or_full_models"]=20;check["candidate_fits"]=fits;check["prediction_rows"]=int(all_predictions.size());check["python_invocations"]=0;check["input_features_sha256"]=sha256(fs::u8path(argv[1]));check["input_splits_sha256"]=sha256(fs::u8path(argv[3]));check["scope"]="Native reproduction of preserved nested development splits; not independent validation";write(out/"checks.json",check.dump());return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
